arguments.query:
dimension activities.surface_or_unknown = case(when: activities.run_surface is null, then: 'unknown', else: activities.run_surface);
explore {
  dimensions {
    run_surface: activities.surface_or_unknown
  }
  measures {
    avg_decoupling: decoupling_calc.avg_decoupling,
    long_runs: decoupling_calc.long_run_count
  }
  sorts {
    avg_decoupling desc
  }
}
